    private function do_fetch_markets($params = array()) {
        /**
         * retrieves all available $markets on the exchange
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-$market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->region] the $region to filter $markets by (e.g. EEA, UK)
         * @return {array[]} an array of ~@link https://docs.ccxt.com/?id=$market-structure $market structures~
         */
        $request = array();
        $region = $this->safe_string_2($params, 'region', 'region', $this->options['region']);
        if ($region !== null) {
            $request['region'] = $region;
        }
        $response = Async\await($this->publicGet10PublicConfigurationPairs($this->extend($request, $params)));
        //
        //     {
        //         "BTC/USD" => {
        //             "base" => "BTC", "quote" => "USD",
        //             "base_step" => "0.0000001", "quote_step" => "0.01",
        //             "min_order_size" => "0.0000001", "max_order_size" => "1000",
        //             "min_order_size_quote" => "0.01", "status" => "active"
        //         }
        //     }
        //
        $markets = $this->safe_dict($response, 'data', $response);
        $keys = is_array($markets) ? array_keys($markets) : array();
        $result = array();
        for ($i = 0; $i < count($keys); $i++) {
            $key = $keys[$i];
            $market = $this->safe_dict($markets, $key, array());
            $base = $this->safe_string($market, 'base');
            $quote = $this->safe_string($market, 'quote');
            $marketId = $base . '-' . $quote;
            $marketData = $this->extend($market, array( 'id' => $marketId ));
            $result[] = $this->parse_market($marketData);
        }
        return $result;
    }

    public function parse_currency(array $currency): array {
        /**
         * parses a $currency from the exchange's $currency data
         * @ignore
         * @param {array} $currency the raw $currency data from the exchange
         * @return {array} a ~@link https://docs.ccxt.com/?$id=$currency-structure $currency structure~
         */
        $id = $this->safe_string_2($currency, 'id', 'symbol', '');
        $code = $this->safe_currency_code($id);
        $name = $this->safe_string($currency, 'name');
        $scale = $this->safe_integer($currency, 'scale');
        $status = $this->safe_string($currency, 'status');
        $active = ($status === 'active');
        $assetType = $this->safe_string($currency, 'asset_type');
        $type = ($assetType === 'crypto') ? 'crypto' : 'fiat';
        $precision = ($scale !== null) ? pow(10, -$scale) : null;
        return array(
            'info' => $currency,
            'id' => $id,
            'code' => $code,
            'name' => $name,
            'active' => $active,
            'type' => $type,
            'deposit' => null,
            'withdraw' => null,
            'precision' => $this->parse_number($precision),
            'fee' => null,
            'limits' => array(
                'amount' => array(
                    'min' => null,
                    'max' => null,
                ),
                'withdraw' => array(
                    'min' => null,
                    'max' => null,
                ),
                'deposit' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
            'networks' => array(),
        );
    }

