    private function do_fetch_currencies($params = array()) {
        /**
         * fetches all available $currencies on the exchange
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->region] the $region to filter $currencies by
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=$currency-structure $currency structures~
         */
        $request = array();
        $region = $this->safe_string_2($params, 'region', 'region', $this->options['region']);
        if ($region !== null) {
            $request['region'] = $region;
        }
        $response = Async\await($this->publicGet10PublicConfigurationCurrencies($this->extend($request, $params)));
        //
        //     {
        //         "BTC" => array( "symbol" => "BTC", "name" => "Bitcoin", "scale" => 8, "asset_type" => "crypto", "status" => "active" ),
        //         "USD" => array( "symbol" => "$", "name" => "US Dollar", "scale" => 2, "asset_type" => "fiat", "status" => "active" )
        //     }
        //
        $currencies = $this->safe_dict($response, 'data', $response);
        $keys = is_array($currencies) ? array_keys($currencies) : array();
        $result = array();
        for ($i = 0; $i < count($keys); $i++) {
            $key = $keys[$i];
            $currency = $this->safe_dict($currencies, $key, array());
            $currencyData = $this->extend($currency, array( 'id' => $key ));
            $parsed = $this->parse_currency($currencyData);
            $code = $this->safe_string($parsed, 'code', '');
            if ($code === '') {
                continue;
            }
            $result[$code] = $parsed;
        }
        return $result;
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        /**
         * parses a $ticker from the exchange's $ticker data
         * @ignore
         * @param {array} $ticker the raw $ticker data from the exchange
         * @param {array} [$market] the $market the $ticker is for
         * @return {array} a ~@link https://docs.ccxt.com/?id=$ticker-structure $ticker structure~
         */
        $tickerSymbol = $this->safe_string($ticker, 'symbol');
        $symbol = $this->safe_symbol($tickerSymbol, $market, '/');
        $bid = $this->safe_string($ticker, 'bid');
        $ask = $this->safe_string($ticker, 'ask');
        $last = $this->safe_string($ticker, 'last_price');
        $high = $this->safe_string($ticker, 'high_24h');
        $low = $this->safe_string($ticker, 'low_24h');
        $priceChange = $this->safe_string($ticker, 'price_change_24h');
        $baseVolume = $this->safe_string($ticker, 'volume_24h');
        $timestamp = $this->safe_integer($ticker, 'timestamp');
        $open = null;
        if ($last !== null && $priceChange !== null) {
            $open = Precise::string_sub($last, $priceChange);
        }
        $percentage = null;
        if ($open !== null && $priceChange !== null) {
            $percentageString = Precise::string_div($priceChange, $open, 8);
            $percentage = $this->parse_number(Precise::string_mul($percentageString, '100'));
        }
        return $this->safe_ticker(array(
            'symbol' => $symbol,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $high,
            'low' => $low,
            'bid' => $bid,
            'bidVolume' => null,
            'ask' => $ask,
            'askVolume' => null,
            'vwap' => null,
            'open' => $open,
            'close' => $last,
            'last' => $last,
            'previousClose' => null,
            'change' => $priceChange,
            'percentage' => $percentage,
            'average' => null,
            'baseVolume' => $baseVolume,
            'quoteVolume' => null,
            'info' => $ticker,
        ), $market);
    }

