    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         * fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each $market
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-$market-$data
         *
         * @param {string[]|null} $symbols unified $symbols of the markets to fetch the $ticker for, all $market tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->region] the $region to fetch tickers for (e.g. EEA, UK)
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=$ticker-structure $ticker structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $request = array();
        if ($symbols !== null) {
            $marketIds = array();
            for ($i = 0; $i < count($symbols); $i++) {
                $symbol = $symbols[$i];
                $market = $this->market($symbol);
                $marketIds[] = $market['id'];
            }
            $request['symbols'] = implode(',', $marketIds);
        }
        $region = $this->safe_string_2($params, 'region', 'region', $this->options['region']);
        if ($region !== null) {
            $request['region'] = $region;
        }
        $response = Async\await($this->publicGet10PublicTickers($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             { "symbol" => "BTC/USD", "bid" => "119950.00", "ask" => "120050.00", "mid" => "120000.00",
        //               "last_price" => "119980.00", "low_24h" => "115000.00", "high_24h" => "122500.00",
        //               "price_change_24h" => "2480.00", "volume_24h" => "135.42000000", "region" => "EEA" }
        //         ),
        //         "metadata" => array( "timestamp" => 1785313433816 )
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $metadata = $this->safe_dict($response, 'metadata', array());
        $timestamp = $this->safe_integer($metadata, 'timestamp');
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $tickerData = $this->safe_dict($data, $i, array());
            $tickerData['timestamp'] = $timestamp;
            $ticker = $this->parse_ticker($tickerData);
            $symbol = $this->safe_string($ticker, 'symbol', '');
            if ($symbol === '') {
                continue;
            }
            $result[$symbol] = $ticker;
        }
        if ($symbols !== null) {
            $filtered = array();
            for ($i = 0; $i < count($symbols); $i++) {
                $s = $symbols[$i];
                if (is_array($result) && array_key_exists($s ?? '', $result)) {
                    $filtered[$s] = $result[$s];
                }
            }
            return $filtered;
        }
        return $result;
    }

    public function fetch_ticker(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($symbol, $params);
    }

    private function do_fetch_ticker(string $symbol, $params = array()) {
        /**
         * fetches a price $ticker for a given market $symbol
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-market-data
         *
         * @param {string} $symbol unified $symbol of the market to fetch the $ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->region] the region to fetch the $ticker for
         * @return {array} a ~@link https://docs.ccxt.com/?id=$ticker-structure $ticker structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $tickers = Async\await($this->fetch_tickers(array( $symbol ), $params));
        $ticker = $this->safe_dict($tickers, $symbol);
        if ($ticker === null) {
            throw new ExchangeError($this->id . ' fetchTicker() could not find $ticker for $symbol ' . $symbol);
        }
        return $ticker;
    }

