    private function do_fetch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * fetches the current order book snapshot for a given $market $symbol
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-$market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum number of orders to return (1-50, default 50)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->region] the $region to fetch the order book for
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-book-structure order book structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $region = $this->safe_string_2($params, 'region', 'region', $this->options['region']);
        if ($region !== null) {
            $request['region'] = $region;
        }
        $response = Async\await($this->publicGet20PublicOrderBookSymbol($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             "asks" => array( array( "price" => "4005.00", "quantity" => "1.7000", "count" => 3 ) ),
        //             "bids" => array( array( "price" => "4000.00", "quantity" => "0.25", "count" => 1 ) )
        //         ),
        //         "metadata" => array( "region" => "UK", "timestamp" => 1785313433816 )
        //     }
        //
        $data = $this->safe_dict($response, 'data', array());
        $metadata = $this->safe_dict($response, 'metadata', array());
        $timestamp = $this->safe_integer($metadata, 'timestamp');
        return $this->parse_order_book($data, $symbol, $timestamp, 'bids', 'asks', 'price', 'quantity');
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        /**
         * parses an OHLCV candle from the exchange's candle data
         * @ignore
         * @param {array} $ohlcv the raw candle data from the exchange
         * @param {array} [$market] the $market the candle is for
         * @return {int[]} an ~@link https://docs.ccxt.com/?id=$ohlcv-structure OHLCV structure~
         */
        $timestamp = $this->safe_integer($ohlcv, 'start');
        $open = $this->safe_number($ohlcv, 'open');
        $high = $this->safe_number($ohlcv, 'high');
        $low = $this->safe_number($ohlcv, 'low');
        $close = $this->safe_number($ohlcv, 'close');
        $volume = $this->safe_number($ohlcv, 'volume');
        return array( $timestamp, $open, $high, $low, $close, $volume );
    }

    public function fetch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick $data for a given $market $symbol
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-$market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV $data for
         * @param {string} $timeframe the length of time each candle represents (e.g. 1m, 5m, 1h, 1d)
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum number of candles to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest candle to fetch
         * @param {string} [$params->region] the $region to fetch candles for
         * @return {int[][]} a list of ~@link https://docs.ccxt.com/?id=ohlcv-structure OHLCV structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'interval' => $this->safe_integer($this->timeframes, $timeframe, 5),
        );
        if ($since !== null) {
            $request['since'] = $since;
        }
        $until = $this->safe_integer_2($params, 'until', 'until');
        if ($until !== null) {
            $request['until'] = $until;
        } else {
            $request['until'] = $this->milliseconds();
        }
        $region = $this->safe_string_2($params, 'region', 'region', $this->options['region']);
        if ($region !== null) {
            $request['region'] = $region;
        }
        $response = Async\await($this->publicGet10PublicCandlesSymbol($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             { "start" => 1785309833816, "open" => "119800.00", "high" => "120100.00",
        //               "low" => "119700.00", "close" => "120000.00", "volume" => "0.25000000" }
        //         ),
        //         "metadata" => array( "region" => "EEA", "timestamp" => 1785313433816 )
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_ohlcvs($data, $market, $timeframe, $since, $limit);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        /**
         * parses a $trade from the exchange's public $trade data
         * @ignore
         * @param {array} $trade the raw $trade data from the exchange
         * @param {array} [$market] the $market the $trade was executed in
         * @return {array} a ~@link https://docs.ccxt.com/?$id=$trade-structure $trade structure~
         */
        $id = $this->safe_string($trade, 'id');
        $tradeSymbol = $this->safe_string($trade, 'symbol');
        $symbol = $this->safe_symbol($tradeSymbol, $market, '/');
        $price = $this->safe_number($trade, 'price');
        $amount = $this->safe_number($trade, 'quantity');
        $side = $this->safe_string_lower($trade, 'side');
        $timestamp = $this->safe_integer($trade, 'timestamp');
        $cost = null;
        if ($price !== null && $amount !== null) {
            $cost = $price * $amount;
        }
        return array(
            'info' => $trade,
            'id' => $id,
            'order' => null,
            'symbol' => $symbol,
            'side' => $side,
            'type' => null,
            'takerOrMaker' => null,
            'price' => $price,
            'amount' => $amount,
            'cost' => $cost,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'fee' => null,
            'fees' => array(),
        );
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the public $trade history for a given $market $symbol
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-public-$market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest $trade to fetch
         * @param {int} [$limit] the maximum number of trades to return (1-1900, default 1900)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest $trade to fetch
         * @param {string} [$params->cursor] pagination $cursor from the previous $response
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=$trade-structure $trade structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $request = array();
        if ($market !== null) {
            $request['symbol'] = $market['id'];
        }
        if ($since !== null) {
            $request['start_date'] = $since;
        }
        $until = $this->safe_integer_2($params, 'until', 'until');
        if ($until !== null) {
            $request['end_date'] = $until;
        } elseif ($since !== null) {
            $request['end_date'] = $this->milliseconds();
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $cursor = $this->safe_string($params, 'cursor');
        if ($cursor !== null) {
            $request['cursor'] = $cursor;
        }
        $response = Async\await($this->publicGet10PublicTradesAll($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             { "id" => "3b2b202b-7668-43cf-a6c8-b3354e7f4c52", "symbol" => "BTC/USD",
        //               "price" => "119980.00", "quantity" => "0.01000000", "side" => "sell", "timestamp" => 1785313433816 }
        //         ),
        //         "metadata" => array( "timestamp" => 1785313433816, "next_cursor" => "..." )
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $trade = $this->safe_dict($data, $i, array());
            $result[] = $this->parse_trade($trade, $market);
        }
        return $this->filter_by_symbol_since_limit($this->sort_by($result, 'timestamp'), $symbol, $since, $limit);
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * fetches the current $balance for the authenticated user
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-$account-$data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=$balance-structure $balance structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $response = Async\await($this->privateGet10Balances($params));
        //
        //     array(
        //         array( "currency" => "BTC", "available" => "1.25000000", "reserved" => "0.10000000", "total" => "1.35000000" ),
        //         array( "currency" => "USD", "available" => "50000.00", "reserved" => "1000.00", "total" => "51000.00", "staked" => "32.00000000" )
        //     )
        //
        $data = (gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response))) ? $response : $this->safe_list($response, 'data', array());
        $result = array( 'info' => $response );
        for ($i = 0; $i < count($data); $i++) {
            $balance = $this->safe_dict($data, $i, array());
            $currency = $this->safe_string($balance, 'currency');
            $code = $this->safe_currency_code($currency);
            if ($code === null) {
                continue;
            }
            $account = $this->account();
            $account['free'] = $this->safe_string($balance, 'available');
            $reserved = $this->safe_string($balance, 'reserved');
            $staked = $this->safe_string($balance, 'staked');
            $used = $reserved;
            if ($staked !== null) {
                $used = ($reserved === null) ? $staked : Precise::string_add($reserved, $staked);
            }
            $account['used'] = $used;
            $account['total'] = $this->safe_string($balance, 'total');
            $result[$code] = $account;
        }
        return $this->safe_balance($result);
    }

    public function parse_order_status(?string $status) {
        /**
         * parses the order $status from the exchange's $status to the unified ccxt $status
         * @ignore
         * @param {string} $status the exchange-specific order $status
         * @return {string|null} the unified order $status
         */
        $statuses = array(
            'pending_new' => 'open',
            'new' => 'open',
            'partially_filled' => 'open',
            'filled' => 'closed',
            'cancelled' => 'canceled',
            'canceled' => 'canceled',
            'rejected' => 'rejected',
            'replaced' => 'open',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_order(array $order, ?array $market = null): array {
        /**
         * parses an $order from the exchange's $order data
         * @ignore
         * @param {array} $order the raw $order data from the exchange
         * @param {array} [$market] the $market the $order was placed in
         * @return {array} an ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        $orderId = $this->safe_string_2($order, 'id', 'venue_order_id');
        $clientOrderId = $this->safe_string($order, 'client_order_id');
        $orderSymbol = $this->safe_string($order, 'symbol');
        $symbol = $this->safe_symbol($orderSymbol, $market, '/');
        $side = $this->safe_string_lower($order, 'side');
        $orderType = $this->safe_string_lower($order, 'type');
        $quantity = $this->safe_string($order, 'quantity');
        $filledQuantity = $this->safe_string($order, 'filled_quantity');
        $leavesQuantity = $this->safe_string($order, 'leaves_quantity');
        $price = $this->safe_string($order, 'price');
        $averageFillPrice = $this->safe_string($order, 'average_fill_price');
        $amount = $this->safe_string($order, 'amount');
        $filledAmount = $this->safe_string($order, 'filled_amount');
        $totalFee = $this->safe_string($order, 'total_fee');
        $feeCurrency = $this->safe_string($order, 'fee_currency');
        $status = $this->parse_order_status($this->safe_string($order, 'status'));
        $timeInForce = $this->safe_string_upper($order, 'time_in_force');
        $createdDate = $this->safe_integer($order, 'created_date');
        $updatedDate = $this->safe_integer($order, 'updated_date');
        $fee = null;
        if ($totalFee !== null) {
            $fee = array(
                'cost' => $this->parse_number($totalFee),
                'currency' => $feeCurrency,
            );
        }
        $amountValue = null;
        if ($quantity !== null) {
            $amountValue = $quantity;
        } elseif ($amount !== null) {
            $amountValue = $amount;
        }
        $filledValue = null;
        if ($filledQuantity !== null) {
            $filledValue = $filledQuantity;
        } elseif ($filledAmount !== null) {
            $filledValue = $filledAmount;
        }
        $remainingValue = null;
        if ($leavesQuantity !== null) {
            $remainingValue = $leavesQuantity;
        }
        return $this->safe_order(array(
            'id' => $orderId,
            'clientOrderId' => $clientOrderId,
            'symbol' => $symbol,
            'side' => $side,
            'type' => $orderType,
            'price' => $this->parse_number($price),
            'average' => $this->parse_number($averageFillPrice),
            'amount' => $this->parse_number($amountValue),
            'filled' => $this->parse_number($filledValue),
            'remaining' => $this->parse_number($remainingValue),
            'status' => $status,
            'timeInForce' => $timeInForce,
            'timestamp' => $createdDate,
            'datetime' => $this->iso8601($createdDate),
            'lastUpdateTimestamp' => $updatedDate,
            'fee' => $fee,
            'info' => $order,
        ), $market);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade $order
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-trading
         *
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'limit' or 'market'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of the base currency you want to trade
         * @param {float} [$price] the $price at which the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a custom client $order id (UUID)
         * @param {float} [$params->cost] the $order $cost in units of the quote currency (alternative to $amount)
         * @param {string} [$params->timeInForce] 'gtc' or 'ioc' for limit orders
         * @param {string[]} [$params->executionInstructions] limit $order instructions, e.g. ['post_only'] or ['allow_taker']
         * @return {array} an ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $clientOrderId = $this->safe_string_2($params, 'clientOrderId', 'client_order_id', $this->uuid());
        $cost = $this->safe_string_2($params, 'cost', 'quote_size');
        $timeInForce = $this->safe_string_lower_2($params, 'timeInForce', 'time_in_force');
        $executionInstructions = $this->safe_list($params, 'executionInstructions', $this->safe_list($params, 'execution_instructions'));
        $orderConfiguration = array();
        if ($type === 'limit') {
            $limitConfig = array();
            if ($cost !== null) {
                $limitConfig['quote_size'] = $this->cost_to_precision($symbol, $cost);
            } else {
                $limitConfig['base_size'] = $this->amount_to_precision($symbol, $amount);
            }
            $limitConfig['price'] = $this->price_to_precision($symbol, $price);
            if ($timeInForce !== null) {
                $limitConfig['time_in_force'] = $timeInForce;
            }
            if ($executionInstructions !== null) {
                $limitConfig['execution_instructions'] = $executionInstructions;
            }
            $orderConfiguration['limit'] = $limitConfig;
        } elseif ($type === 'market') {
            if ($timeInForce !== null) {
                throw new InvalidOrder($this->id . ' createOrder() $timeInForce is only supported for limit orders');
            }
            if ($executionInstructions !== null) {
                throw new InvalidOrder($this->id . ' createOrder() $executionInstructions are only supported for limit orders');
            }
            $marketConfig = array();
            if ($cost !== null) {
                $marketConfig['quote_size'] = $this->cost_to_precision($symbol, $cost);
            } else {
                $marketConfig['base_size'] = $this->amount_to_precision($symbol, $amount);
            }
            $orderConfiguration['market'] = $marketConfig;
        } else {
            throw new InvalidOrder($this->id . ' createOrder() does not support $order $type ' . $type);
        }
        $request = array(
            'client_order_id' => $clientOrderId,
            'symbol' => $market['id'],
            'side' => $side,
            'order_configuration' => $orderConfiguration,
        );
        $response = Async\await($this->privatePost10Orders($this->extend($request, $this->omit($params, array( 'cost', 'quote_size', 'clientOrderId', 'client_order_id', 'timeInForce', 'time_in_force', 'executionInstructions', 'execution_instructions' )))));
        //
        //     {
        //         "data" => array(
        //             array( "venue_order_id" => "7a52e92e-8639-4fe1-abaa-68d3a2d5234b", "client_order_id" => "...", "state" => "new" )
        //         )
        //     }
        //
        $data = $this->safe_value($response, 'data', array());
        $orderData = (gettype($data) === 'array' && array_keys($data) === array_keys(array_keys($data))) ? $this->safe_dict($data, 0, array()) : $this->safe_dict($response, 'data', array());
        $venueOrderId = $this->safe_string($orderData, 'venue_order_id');
        $state = $this->safe_string($orderData, 'state');
        $order = $this->parse_order($this->extend($orderData, array(
            'id' => $venueOrderId,
            'symbol' => $market['id'],
            'status' => $state,
            'side' => $side,
            'type' => $type,
        )), $market);
        return $order;
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order(...))($id, $symbol, $params);
    }

    private function do_cancel_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * cancels an open order by its $id
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-trading
         *
         * @param {string} $id the order $id (venue order $id)
         * @param {string} $symbol not used by this exchange
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/?$id=order-structure order structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $request = array(
            'venue_order_id' => $id,
        );
        $response = Async\await($this->privateDelete10OrdersVenueOrderId($this->extend($request, $params)));
        return $this->safe_order(array(
            'info' => $response,
            'id' => $id,
            'status' => 'canceled',
        ));
    }

    public function cancel_all_orders(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders(...))($symbol, $params);
