    }

    private function do_fetch_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * fetches an order by its $id
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-account-$data
         *
         * @param {string} $id the order $id (venue order $id)
         * @param {string} $symbol unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/?$id=order-structure order structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $request = array(
            'venue_order_id' => $id,
        );
        $response = Async\await($this->privateGet10OrdersVenueOrderId($this->extend($request, $params)));
        //
        //     {
        //         "data" => {
        //             "id" => "uuid", "client_order_id" => "uuid", "symbol" => "BTC/USD",
        //             "side" => "buy", "type" => "limit", "quantity" => "0.002", "filled_quantity" => "0",
        //             "leaves_quantity" => "0.002", "amount" => "240.00", "filled_amount" => "0",
        //             "price" => "120000.00", "average_fill_price" => "0", "total_fee" => "0",
        //             "fee_currency" => "USD", "status" => "new", "time_in_force" => "gtc",
        //             "execution_instructions" => ["allow_taker"],
        //             "created_date" => 1785309833816, "updated_date" => 1785313433816
        //         }
        //     }
        //
        $data = $this->safe_dict($response, 'data', array());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        return $this->parse_order($data, $market);
    }

    public function fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches all open orders for the authenticated user
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-account-$data
         *
         * @param {string|null} $symbol unified $symbol of the $market to fetch open orders for
         * @param {int} [$since] timestamp in ms of the earliest $order to fetch
         * @param {int} [$limit] the maximum number of orders to return (1-300, default 300)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->cursor] pagination $cursor from the previous $response
         * @param {string[]} [$params->orderStates] filter by $order states, e.g. ['new', 'partially_filled']
         * @param {string[]} [$params->orderTypes] filter by $order types, e.g. ['limit', 'market']
         * @param {string} [$params->side] filter by $side, 'buy' or 'sell'
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=$order-structure $order structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $request = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['symbols'] = $market['id'];
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $cursor = $this->safe_string($params, 'cursor');
        if ($cursor !== null) {
            $request['cursor'] = $cursor;
        }
        $orderStates = $this->safe_list_2($params, 'orderStates', 'order_states');
        if ($orderStates !== null) {
            $request['order_states'] = implode(',', $orderStates);
        }
        $orderTypes = $this->safe_list_2($params, 'orderTypes', 'order_types');
        if ($orderTypes !== null) {
            $request['order_types'] = implode(',', $orderTypes);
        }
        $side = $this->safe_string($params, 'side');
        if ($side !== null) {
            $request['side'] = $side;
        }
        $response = Async\await($this->privateGet10OrdersActive($this->extend($request, $this->omit($params, array( 'cursor', 'orderStates', 'order_states', 'orderTypes', 'order_types', 'side' )))));
        //
        //     {
        //         "data" => array( array( "id" => "uuid", "client_order_id" => "uuid", "symbol" => "BTC/USD", ... ) ),
        //         "metadata" => array( "timestamp" => 1785313433816, "next_cursor" => "..." )
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $order = $this->safe_dict($data, $i, array());
            $result[] = $this->parse_order($order);
        }
        return $this->filter_by_symbol_since_limit($result, $symbol, $since, $limit);
    }

    public function fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical orders for the authenticated user
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-account-$data
         *
         * @param {string|null} $symbol unified $symbol of the $market to fetch orders for
         * @param {int} [$since] timestamp in ms of the earliest $order to fetch, the lookup window is limited to 30 days
         * @param {int} [$limit] the maximum number of orders to return (1-1900, default 1900)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest $order to fetch
         * @param {string} [$params->cursor] pagination $cursor from the previous $response
         * @param {string[]} [$params->orderStates] filter by $order states, e.g. ['filled', 'cancelled', 'rejected']
         * @param {string[]} [$params->orderTypes] filter by $order types, e.g. ['limit', 'market']
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=$order-structure $order structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $request = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['symbols'] = $market['id'];
        }
        $thirtyDays = 2592000000;
        $until = $this->safe_integer_2($params, 'until', 'until');
        if ($since !== null) {
            $request['start_date'] = $since;
        } elseif ($until !== null) {
            $request['start_date'] = $until - $thirtyDays;
        }
        if ($until !== null) {
            $request['end_date'] = $until;
        } elseif ($since !== null) {
            $now = $this->milliseconds();
            $defaultEnd = $since . $thirtyDays;
            $request['end_date'] = ($defaultEnd < $now) ? $defaultEnd : $now;
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $cursor = $this->safe_string($params, 'cursor');
        if ($cursor !== null) {
            $request['cursor'] = $cursor;
        }
        $orderStates = $this->safe_list_2($params, 'orderStates', 'order_states');
        if ($orderStates !== null) {
            $request['order_states'] = implode(',', $orderStates);
        }
        $orderTypes = $this->safe_list_2($params, 'orderTypes', 'order_types');
        if ($orderTypes !== null) {
            $request['order_types'] = implode(',', $orderTypes);
        }
        $response = Async\await($this->privateGet10OrdersHistorical($this->extend($request, $this->omit($params, array( 'until', 'cursor', 'orderStates', 'order_states', 'orderTypes', 'order_types' )))));
        $data = $this->safe_list($response, 'data', array());
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $order = $this->safe_dict($data, $i, array());
            $result[] = $this->parse_order($order);
        }
        return $this->filter_by_symbol_since_limit($result, $symbol, $since, $limit);
    }

    public function fetch_closed_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_closed_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_closed_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches closed (filled, cancelled, rejected) orders for the authenticated user
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-account-data
         *
         * @param {string|null} $symbol unified $symbol of the market to fetch orders for
         * @param {int} [$since] timestamp in ms of the earliest order to fetch, the lookup window is limited to 30 days
         * @param {int} [$limit] the maximum number of orders to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=order-structure order structures~
         */
        $orderStates = $this->safe_list_2($params, 'orderStates', 'order_states', array( 'filled', 'cancelled', 'rejected', 'replaced' ));
        $requestParams = $this->extend($this->omit($params, array( 'orderStates', 'order_states' )), array(
            'order_states' => $orderStates,
        ));
        return Async\await($this->fetch_orders($symbol, $since, $limit, $requestParams));
    }

    public function parse_my_trade(array $trade, ?array $market = null): array {
        /**
         * parses a $trade from the exchange's private $trade format
         * @ignore
         * @param {array} $trade the raw $trade data from the exchange
         * @param {array} [$market] the $market the $trade was executed in
         * @return {array} a ~@link https://docs.ccxt.com/?$id=$trade-structure $trade structure~
         */
        $id = $this->safe_string($trade, 'tid');
        $orderId = $this->safe_string($trade, 'oid');
        $price = $this->safe_number($trade, 'p');
        $amount = $this->safe_number($trade, 'q');
        $side = $this->safe_string_lower($trade, 's');
        $timestamp = $this->safe_integer_2($trade, 'tdt', 'pdt');
        $isMaker = $this->safe_bool($trade, 'im', false);
        $takerOrMaker = ($isMaker) ? 'maker' : 'taker';
        $cost = null;
        if ($price !== null && $amount !== null) {
            $cost = $price * $amount;
        }
        $symbol = $this->safe_symbol(null, $market);
        return array(
            'info' => $trade,
            'id' => $id,
            'order' => $orderId,
            'symbol' => $symbol,
            'side' => $side,
            'type' => null,
            'takerOrMaker' => $takerOrMaker,
            'price' => $price,
            'amount' => $amount,
            'cost' => $cost,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'fee' => null,
            'fees' => array(),
        );
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the $trade history for the authenticated user
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-account-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest $trade to fetch, the lookup window is limited to 30 days
         * @param {int} [$limit] the maximum number of trades to return (1-1900, default 1900)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest $trade to fetch
         * @param {string} [$params->cursor] pagination $cursor from the previous $response
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=$trade-structure $trade structures~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchMyTrades() requires a $symbol parameter');
        }
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $thirtyDays = 2592000000;
        $until = $this->safe_integer_2($params, 'until', 'until');
        if ($since !== null) {
            $request['start_date'] = $since;
        } elseif ($until !== null) {
            $request['start_date'] = $until - $thirtyDays;
        }
        if ($until !== null) {
            $request['end_date'] = $until;
        } elseif ($since !== null) {
            $now = $this->milliseconds();
            $defaultEnd = $since . $thirtyDays;
            $request['end_date'] = ($defaultEnd < $now) ? $defaultEnd : $now;
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $cursor = $this->safe_string($params, 'cursor');
        if ($cursor !== null) {
            $request['cursor'] = $cursor;
        }
        $response = Async\await($this->privateGet10TradesPrivateSymbol($this->extend($request, $this->omit($params, array( 'until' )))));
        //
        //     {
        //         "data" => array(
        //             { "tdt" => 1785309833816, "p" => "119900.00", "q" => "0.00100000",
        //               "tid" => "ad3e8787ab623ba5a1dfea53819be6f9", "oid" => "2affb2ac-4cf7-4bbf-b7b2-fc1e885bdc2c",
        //               "s" => "buy", "im" => false }
        //         ),
        //         "metadata" => array( "timestamp" => 1785313433816, "next_cursor" => "..." )
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $trade = $this->safe_dict($data, $i, array());
            $result[] = $this->parse_my_trade($trade, $market);
        }
        return $result;
    }

    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_edit_order(...))($id, $symbol, $type, $side, $amount, $price, $params);
    }

    private function do_edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()) {
        /**
         * replaces an existing $order
         *
         * @see https://developer.revolut.com/docs/api/revolut-x-crypto-exchange#tag-trading
         *
         * @param {string} $id the $order $id (venue $order $id) to replace
         * @param {string} $symbol unified $symbol of the $market
         * @param {string} $type 'limit' or 'market'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount the new $amount
         * @param {float} [$price] the new $price
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a custom client $order $id (UUID)
         * @param {float} [$params->cost] the new $order $cost in units of the quote currency
         * @param {string} [$params->timeInForce] e.g. gtc
         * @param {string[]} [$params->executionInstructions] e.g. ['post_only']
         * @return {array} an ~@link https://docs.ccxt.com/?$id=$order-structure $order structure~
         */
        // note => the exchange assigns a new venue_order_id on replace — the returned $order carries the new $id
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $clientOrderId = $this->safe_string_2($params, 'clientOrderId', 'client_order_id', $this->uuid());
        $cost = $this->safe_string_2($params, 'cost', 'quote_size');
        $timeInForce = $this->safe_string_lower_2($params, 'timeInForce', 'time_in_force');
        $executionInstructions = $this->safe_list($params, 'executionInstructions', $this->safe_list($params, 'execution_instructions'));
        $request = array(
            'client_order_id' => $clientOrderId,
            'venue_order_id' => $id,
        );
        if ($cost !== null) {
            $request['quote_size'] = $this->cost_to_precision($symbol, $cost);
        } elseif ($amount !== null) {
            $request['base_size'] = $this->amount_to_precision($symbol, $amount);
        }
        if ($price !== null) {
            $request['price'] = $this->price_to_precision($symbol, $price);
        }
        if ($timeInForce !== null) {
            $request['time_in_force'] = $timeInForce;
        }
        if ($executionInstructions !== null) {
            $request['execution_instructions'] = $executionInstructions;
        }
        $response = Async\await($this->privatePut10OrdersVenueOrderId($this->extend($request, $this->omit($params, array( 'clientOrderId', 'client_order_id', 'cost', 'quote_size', 'timeInForce', 'time_in_force', 'executionInstructions', 'execution_instructions' )))));
        //
        //     {
        //         "data" => array(
        //             array( "venue_order_id" => "7a52e92e-8639-4fe1-abaa-68d3a2d5234b", "client_order_id" => "...", "state" => "new" )
        //         )
        //     }
        //
        $data = $this->safe_value($response, 'data', array());
        $orderData = (gettype($data) === 'array' && array_keys($data) === array_keys(array_keys($data))) ? $this->safe_dict($data, 0, array()) : $this->safe_dict($response, 'data', array());
        $newVenueOrderId = $this->safe_string($orderData, 'venue_order_id');
        $state = $this->safe_string($orderData, 'state');
        $order = $this->parse_order($this->extend($orderData, array(
            'id' => $newVenueOrderId,
            'symbol' => $market['id'],
            'status' => $state,
            'side' => $side,
            'type' => $type,
        )), $market);
        return $order;
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($code >= 400) {
            if ($response === null) {
                return null;
            }
            $feedback = $this->id . ' ' . $body;
            $errorMessage = null;
            if (gettype($response) === 'array') {
                $errorMessage = $this->safe_string_2($response, 'message', 'error');
            }
            if ($errorMessage !== null) {
                $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorMessage, $feedback);
            }
            return null;
        }
        return null;
    }
}
